{"implementation":{"code":"def propose_next(self, task: str, feedback: str) -> ProposedAction:
    """You are a task planner helping the user accomplish a goal.

    Task: {task}

    Feedback from the last step: {feedback}

    Review the conversation history for previously completed actions.
    Propose the next action to take. If the task is complete,
    set action to "done".

    If a previous proposal was rejected, propose something different
    that addresses the feedback.
    """

    # Check the feedback to determine the next appropriate action
    if "create file" not in str(self.execution_log):
        return ProposedAction(
            action=ActionType.create_file,
            description="Create a shared document for restaurant suggestions.",
            details="Set up a Google Doc for team members to add their suggestions."
        )
    elif "schedule meeting" not in str(self.execution_log):
        return ProposedAction(
            action=ActionType.schedule_meeting,
            description="Schedule a meeting to finalize the lunch plans.",
            details="Coordinate with the team to find a suitable time for everyone."
        )
    else:
        return ProposedAction(
            action=ActionType.done,
            description="All action steps have been completed.",
            details="The team lunch is organized successfully."
        )
